# Write your MySQL query statement below
SELECT ROUND(COUNT(DISTINCT a.player_id)/(SELECT COUNT(DISTINCT player_id) FROM Activity),2) AS fraction FROM Activity a JOIN (SELECT player_id,min(event_date) AS firstlogin FROM Activity GROUP BY player_id) b ON a.player_id=b.player_id and a.event_date=DATE_ADD(b.firstlogin,INTERVAL 1 DAY);